<script lang="ts">
  import { invoke, isTauri } from '@tauri-apps/api/core';
  import { onMount } from 'svelte';
  import { RefreshCw, ShieldCheck, TriangleAlert } from 'lucide-svelte';
  import Visualizations from '$lib/prismatik/Visualizations.svelte';

  type Position={symbol:string;quantity:string;markPriceMicros?:number;marketValueMicros?:string;cashFlowMicros:string;unrealizedPnlMicros?:string;markEvidenceId?:string};
  type Portfolio={mode:'paper';liveExecutionAvailable:false;fills:unknown[];positions:Position[];quoteProviderCount:number;reconciliationState:'verified';recoveredCommits:number;releasedOrphans:number;grossExposureMicros:string;netMarketValueMicros:string;totalCashFlowMicros:string;totalUnrealizedPnlMicros?:string;largestPositionConcentrationPpm?:number;markedPositionCount:number;unmarkedPositionCount:number;message:string};
  let portfolio=$state<Portfolio|null>(null);let loading=$state(false);let error=$state('');
  const numeric=(value:string|number|undefined)=>value===undefined?undefined:Number(value);
  const money=(value:string|number|undefined)=>{const amount=numeric(value);return amount===undefined||!Number.isFinite(amount)?'—':`${amount<0?'-':''}$${(Math.abs(amount)/1e6).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`};
  const percent=(ppm:number|undefined)=>ppm===undefined?'—':`${(ppm/10000).toFixed(1)}%`;
  const exposure=(position:Position)=>Math.abs(numeric(position.marketValueMicros)??0);
  let ranked=$derived((portfolio?.positions??[]).slice().sort((a,b)=>exposure(b)-exposure(a)));
  function allocation(position:Position){const gross=Math.abs(numeric(portfolio?.grossExposureMicros)??0);return gross>0?Math.min(100,exposure(position)/gross*100):0}
  async function load(){if(!isTauri())return;loading=true;error='';try{portfolio=await invoke<Portfolio>('get_paper_oms')}catch(cause){error=String(cause)}finally{loading=false}}
  onMount(()=>{void load();const timer=setInterval(load,15000);return()=>clearInterval(timer)});
</script>

<svelte:head><title>Portfolio intelligence · PRISMATIK</title></svelte:head>
<main class="portfolio">
  <header><div><span>RISK OBSERVATORY / REAL MARKS · PAPER LEDGER</span><h1>Portfolio intelligence</h1><p>Exact positions and cash flow are reconstructed from immutable native paper fills. Exposure and P&amp;L appear only where a current real provider mark exists.</p></div><div class="actions"><div class="mode"><i></i><b>PAPER ONLY</b><small>NO LIVE ACCOUNTS</small></div><button onclick={load} disabled={loading}><span class:spin={loading}><RefreshCw size={14}/></span>{loading?'REFRESHING':'REFRESH MARKS'}</button></div></header>

  {#if error}<section class="error"><TriangleAlert size={18}/><div><b>Portfolio unavailable</b><p>{error}</p></div></section>{/if}

  <section class="metrics">
    <article><span>GROSS EXPOSURE</span><b>{money(portfolio?.grossExposureMicros)}</b><small>Absolute real-mark value</small></article>
    <article><span>NET MARKET VALUE</span><b>{money(portfolio?.netMarketValueMicros)}</b><small>Long minus short</small></article>
    <article><span>PAPER P&amp;L</span><b class:positive={(numeric(portfolio?.totalUnrealizedPnlMicros)??0)>0} class:negative={(numeric(portfolio?.totalUnrealizedPnlMicros)??0)<0}>{money(portfolio?.totalUnrealizedPnlMicros)}</b><small>{portfolio?.unmarkedPositionCount?'Withheld: incomplete marks':'All positions marked'}</small></article>
    <article><span>LARGEST CONCENTRATION</span><b>{percent(portfolio?.largestPositionConcentrationPpm)}</b><small>Share of gross exposure</small></article>
    <article><span>MARK COVERAGE</span><b>{portfolio?`${portfolio.markedPositionCount}/${portfolio.positions.length}`:'—'}</b><small>{portfolio?.quoteProviderCount??0} real quote providers</small></article>
  </section>

  <section class="health"><div><span class="health-icon"><ShieldCheck size={17}/></span><span>CAPITAL RECONCILIATION</span><b>{portfolio?.reconciliationState?.toUpperCase()??'CHECKING'}</b><small>{portfolio?`${portfolio.recoveredCommits} recovered commits · ${portfolio.releasedOrphans} released pre-fill reservations`:'Auditing durable journals'}</small></div><a href="/workspace/autonomy">CAPITAL LIMITS →</a></section>

  <section class="body">
    <div class="positions"><div class="section-head"><div><span>EXPOSURE MAP</span><h2>Paper positions</h2></div><b>{portfolio?.positions.length??0} INSTRUMENTS</b></div>
      <div class="position-grid">{#each ranked as position}<article class:unmarked={!position.markEvidenceId}><header><div><b>{position.symbol}</b><span>{Number(position.quantity)>=0?'LONG / FLAT':'SHORT'}</span></div><strong>{position.quantity}</strong></header><div class="bar"><i style={`width:${allocation(position)}%`}></i></div><dl><dt>ALLOCATION</dt><dd>{allocation(position).toFixed(1)}%</dd><dt>REAL MARK</dt><dd>{money(position.markPriceMicros)}</dd><dt>MARKET VALUE</dt><dd>{money(position.marketValueMicros)}</dd><dt>PAPER P&amp;L</dt><dd class:positive={(numeric(position.unrealizedPnlMicros)??0)>0} class:negative={(numeric(position.unrealizedPnlMicros)??0)<0}>{money(position.unrealizedPnlMicros)}</dd></dl><footer>{position.markEvidenceId??'No current real mark · aggregate P&L withheld'}</footer></article>{:else}<div class="empty"><b>No paper exposure</b><p>Connect a market provider, configure a trading envelope, and use Orders to create an evidence-backed paper fill. No sample portfolio is fabricated.</p><a href="/workspace/orders">OPEN PAPER OMS →</a></div>{/each}</div>
    </div>
    <aside><div class="exposure-viz"><span>EXPOSURE RING</span><div class="viz-host"><Visualizations only={['portfolio']} /></div></div><span>ACCOUNT BOUNDARY</span><h2>What this portfolio is—and is not</h2><p>This surface represents only PRISMATIK’s local paper ledger. It does not imply a broker connection, buying power, settled cash, margin availability, tax lots, custody, or live positions.</p><dl><dt>FILL SOURCE</dt><dd>Immutable native paper OMS</dd><dt>VALUATION</dt><dd>Current governed real quotes</dd><dt>CASH FLOW</dt><dd>{money(portfolio?.totalCashFlowMicros)}</dd><dt>LIVE BROKER</dt><dd>UNAVAILABLE</dd></dl><a href="/workspace/integrations">REVIEW INTEGRATIONS →</a></aside>
  </section>
</main>

