:1180px){.metrics{grid-template-columns:repeat(3,1fr)}.body{grid-template-columns:1fr}aside{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}aside>a{align-self:end}}@media(max-width:720px){.portfolio>header,.health,.health>div{display:block}.actions{margin-top:12px}.actions>button{padding:10px}.metrics{grid-template-columns:1fr 1fr}.health>*{display:block;margin:6px 0}aside{display:block}}@media(max-width:480px){.metrics{grid-template-columns:1fr}}
